    OR DATABASEPROPERTYEX(DB_NAME(),'IsRecursiveTriggersEnabled')=1
    THROW 50004, 'Compras requiere nested triggers habilitado y RECURSIVE_TRIGGERS OFF, como indica Triggers2.sql.', 1;
